<div class="flex flex-wrap gap-2 mb-4"><a class="btn btn-outline btn-sm" href="<?= e(url('/admin/orders')) ?>">← Orders</a><a class="btn btn-soft btn-sm" target="_blank" href="<?= e(url('/admin/orders/' . $o['id'] . '/print')) ?>"><?= icon('printer', 'w-4 h-4') ?> Print</a></div>
