  <?php if ($o['status'] === 'cancelled'): ?><p class="text-sm muted">Cancelled orders can't be reopened.</p><?php else: ?><select class="select" name="status"><?php foreach (order_statuses() as $k => $l): ?><option value="<?= $k ?>" <?= $o['status'] === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select><input class="input" name="note" maxlength="250" placeholder="Note shown to customer (optional)"><button class="btn btn-primary w-full">Update status</button><p class="hint">Cancelling restores stock automatically. Customers see this on Order Tracking.</p><?php endif; ?></form>
  <form method="post" action="<?= e(url('/admin/orders/' . $o['id'] . '/details')) ?>" class="card p-5 space-y-3"><?= csrf_field() ?><h3 class="font-bold">Payment & notes</h3><div><label class="label">Payment method</label><div class="text-sm"><?= e($o['payment_method']) ?></div></div>
  <div><label class="label" for="payment_status">Payment status</label><select class="select" id="payment_status" name="payment_status"><?php foreach (['pending', 'paid', 'failed', 'refunded'] as $s): ?><option <?= $o['payment_status'] === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select></div>
